import { CONFIG, PEOPLE, AD_CATEGORIES, person, canEdit, seed, applyContentUpdates, dateAfter, eventUsed, tripUsed, registerEvent, cancelRegistration, bookTrip, decideBooking, cancelBooking, removePost, savePostLocally, startConversation, sendMessage, reportPost, resolveReport } from './model.js';
import { villageArt, cardArt, mapArt } from './art.js';
import { defaultArt, photoSource, preparePhoto } from './photos.js';

const icons={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',calendar:'M5 5h14v16H5Z M8 3v4m8-4v4M5 10h14m-10 4h1m4 0h1m-6 3h1',car:'m3 13 3-7h12l3 7v6H3Z M3 13h18M7 16h1m8 0h1M6 19v2m12-2v2',tag:'M3 3h8l10 10-8 8L3 11Z M7 7h.01',trail:'M3 20 10 5l5 10 3-6 4 11Z M8 9l3 3 2-2',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Z M10 21h4',chat:'M3 4h18v13H9l-6 4Z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',users:'M14 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M2 21v-2a8 8 0 0 1 16 0v2 M17 3a4 4 0 0 1 0 8m3 3a7 7 0 0 1 2 7',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0 M14 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',close:'m6 6 12 12M6 18 18 6',check:'m4 12 5 5L20 6',edit:'m4 16 12-12 4 4L8 20H4Z m10-10 4 4',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',flag:'M5 22V3m0 1h14l-4 5 4 5H5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z m-5 10 3 3 6-6',leaf:'M20 3C8 1 2 6 4 14s16 8 16-11 M4 21 15 10',refresh:'M20 8A9 9 0 1 0 21 14M20 3v5h-5',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5',lock:'M5 10h14v11H5Z M8 10V6a4 4 0 0 1 8 0v4',heart:'M12 21 3 12C-2 4 8-1 12 6c4-7 14-2 9 6Z',bike:'M10 16a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M22 16a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M6 16l5-9 7 9m-9-9h6m0-4h3l1 5',walk:'M14 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0 M10 9l3-2 3 4 4 1m-7-5-3 8-5 6m5-6 6 2 1 5M10 9 7 13H3',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6m0-10v1',chevron:'m9 5 7 7-7 7',repeat:'m17 2 4 4-4 4M3 11V6h18M7 22l-4-4 4-4m14-1v5H3',mail:'M3 5h18v14H3Z m0 0 9 8 9-8',minus:'M5 12h14',logout:'M9 4H4v16h5m5-14 6 6-6 6m-6-6h12',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.leaf}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageWarning='', photoDraft=null;
function load(){try{const raw=JSON.parse(localStorage.getItem(CONFIG.storageKey));if(raw?.version===1&&['events','trips','ads','trails','registrations','bookings','notifications','conversations','reports','favorites'].every(k=>Array.isArray(raw[k]))){raw.profile=person(raw.profile)?raw.profile:'guest';return applyContentUpdates(raw);}}catch{storageWarning='Les données locales étaient indisponibles. Une nouvelle démonstration a été chargée.';}return seed();}
let state=load(), query='', filter='Tout', selectedTrail='r1', zoom=1, activeConversation=null, deferredInstall=null, focusBeforeDialog=null;
const $=s=>document.querySelector(s);
const current=()=>person(state.profile);
const mine=p=>p.owner===state.profile;
const collectionFor={evenements:'events',trajets:'trips',annonces:'ads',balades:'trails'};
const navs=[['accueil','home','Le village'],['evenements','calendar','Événements'],['trajets','car','Trajets'],['annonces','tag','Petites annonces'],['balades','trail','Balades']];
const route=()=>{const r=location.hash.replace('#/','').split('?')[0];return ['accueil','evenements','trajets','annonces','balades','messages','activite','notifications','admin'].includes(r)?r:'accueil';};
const dateText=(d,options={weekday:'short',day:'numeric',month:'short'})=>new Intl.DateTimeFormat('fr-FR',options).format(new Date(/^\d{4}-\d{2}-\d{2}$/.test(d)?`${d}T12:00:00`:d));
const timeText=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)?'Horaire à préciser':dateText(d,{hour:'2-digit',minute:'2-digit'});
const longDate=d=>dateText(d,{weekday:'long',day:'numeric',month:'long'});
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const statusText={pending:'À confirmer',confirmed:'Confirmé',waiting:'Liste d’attente',declined:'Refusé',cancelled:'Annulé','cancelled-event':'Événement annulé','cancelled-trip':'Trajet annulé'};
const activePost=p=>!p.deleted;
const matches=p=>`${p.title} ${p.description} ${p.location} ${p.to||''} ${p.category||''} ${person(p.owner)?.name||''}`.toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr'));
const unread=()=>state.notifications.filter(n=>n.userId===state.profile&&!n.read).length;
function persist(){try{localStorage.setItem(CONFIG.storageKey,JSON.stringify(state));}catch{storageWarning='Stockage indisponible : vos modifications dureront uniquement pendant cette session.';}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
function action(fn){try{const result=fn();persist();return {ok:true,result};}catch(e){const error=$('#form-error');if(error){error.textContent=e.message;error.focus();}else toast(e.message);return {ok:false};}}
function postVisual(p,type){
  const src=photoSource(p.photo);
  return `<span class="post-visual">${cardArt(defaultArt(type))}${src?`<img class="post-photo" src="${esc(src)}" alt="" decoding="async">`:''}</span>`;
}
function photoEditor(){return `<fieldset class="photo-editor"><legend>Photo <span>(facultative)</span></legend><div id="photo-preview" class="photo-preview"></div><div class="photo-actions"><label class="btn secondary photo-picker"><span id="photo-button-text">Ajouter une photo</span><input id="post-photo" type="file" accept="image/jpeg,image/png,image/webp" aria-labelledby="photo-button-text" aria-describedby="photo-help photo-error"></label><button class="btn secondary" type="button" data-action="remove-photo" hidden>Retirer la photo</button></div><p id="photo-status" class="fine" role="status"></p><p id="photo-help" class="fine">JPEG, PNG ou WebP · 10 Mo maximum. Sans photo, une illustration s’affiche automatiquement. Dans ce pilote, les photos sont allégées et conservées uniquement dans ce navigateur.</p><p id="photo-error" class="photo-error" role="alert"></p></fieldset>`;}
function updatePhotoEditor(){
  const draft=photoDraft;if(!draft?.form.isConnected)return;
  $('#photo-preview').innerHTML=postVisual({photo:draft.photo},draft.type);
  $('#photo-button-text').textContent=draft.photo?'Remplacer la photo':'Ajouter une photo';
  $('[data-action="remove-photo"]').hidden=!draft.photo;
  $('#photo-status').textContent=draft.busy?'Préparation de la photo…':!draft.photo?'Aucune photo · illustration par défaut':draft.photo.startsWith('sample:')?'Photo d’exemple · illustration du pilote':'Votre photo est prête.';
  draft.form.querySelector('[type="submit"]').disabled=!!draft.busy;
  $('#photo-preview').setAttribute('aria-busy',String(!!draft.busy));
}
async function uploadPhoto(input){
  const draft=photoDraft,file=input.files?.[0];if(!draft||!file)return;
  const request=++draft.request;draft.busy=true;$('#photo-error').textContent='';updatePhotoEditor();
  try{
    const photo=await preparePhoto(file);
    if(photoDraft===draft&&draft.form.isConnected&&draft.request===request)draft.photo=photo;
  }catch(error){
    if(photoDraft===draft&&draft.form.isConnected&&draft.request===request)$('#photo-error').textContent=error.message;
  }finally{
    if(photoDraft===draft&&draft.form.isConnected&&draft.request===request){draft.busy=false;input.value='';updatePhotoEditor();}
  }
}
function avatar(id,small=false){const p=person(id);return `<span class="avatar ${small?'small':''}" style="--avatar:${p?.color||'#e4e8da'}">${esc(p?.initials||'V')}</span>`;}
function author(p){return `<span class="author">${avatar(p.owner,true)} ${esc(person(p.owner)?.short||'Habitant')}<span>· ${mine(p)?'Votre publication':'Profil démo'}</span></span>`;}
function empty(title,description,button=''){return `<div class="empty">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${button}</div>`;}
function pageTitle(kicker,title,description,button=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${button}</div>`;}
function publishButton(label='Publier',type=''){return `<button class="btn primary" data-action="compose" data-type="${type}">${icon('plus')}${label}</button>`;}
function gated(){return `<div class="gate"><span class="gate-icon">${icon('lock')}</span><p class="eyebrow">Entre habitants</p><h1>Faisons connaissance.</h1><p>Les trajets et les petites annonces se partagent entre membres du village. Choisissez un profil de démonstration pour découvrir la suite.</p><button class="btn primary" data-action="profiles">Essayer un profil habitant ${icon('arrow')}</button><p class="fine">Démonstration : aucune création de compte nécessaire.</p></div>`;}
function render(){
  const r=route(), u=current();
  $('#app').innerHTML=`<div class="demo-bar" role="region" aria-label="Mode démonstration"><span><span class="demo-dot"></span><strong>Village en démo</strong><span class="demo-long"> · Inscriptions et messages sur cet appareil uniquement</span></span><button data-action="about">Comment ça marche ${icon('info')}</button></div>
  <header class="topbar"><a href="#/accueil" class="brand" aria-label="Prémeyzel, accueil"><img src="./assets/icon.svg" alt="" width="42" height="42"><span>Prémeyzel<small>ENTRE VOISINS</small></span></a><div class="header-actions"><button class="icon-button" data-action="install" aria-label="Installer l’application" title="Installer">${icon('download')}</button>${u?`<a class="icon-button" href="#/messages" aria-label="Messages">${icon('chat')}</a><a class="icon-button notification-icon" href="#/notifications" aria-label="Notifications${unread()?`, ${unread()} non lues`:''}">${icon('bell')}${unread()?`<span class="count-dot">${unread()>9?'9+':unread()}</span>`:''}</a>`:''}<button class="profile-button" data-action="profiles" aria-label="Changer de profil : ${u?esc(u.short):'Visiteur'}">${avatar(state.profile)}<span>${u?esc(u.short):'Visiteur'}<small>${u?.admin?'Administration':u?'Profil démo':'Découvrir'}</small></span>${icon('chevron')}</button></div></header>
  <div class="layout"><aside class="sidebar"><nav aria-label="Navigation principale">${navs.map(([key,i,label])=>`<a href="#/${key}" class="nav-item ${r===key?'active':''}" ${r===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${!u&&['trajets','annonces'].includes(key)?icon('lock','tiny'):''}</a>`).join('')}</nav><div class="sidebar-divider"></div>${u?`<a class="nav-item ${r==='activite'?'active':''}" href="#/activite">${icon('user')}<span>Mon activité</span></a>`:''}${u?.admin?`<a class="nav-item ${r==='admin'?'active':''}" href="#/admin">${icon('shield')}<span>Administration</span></a>`:''}<div class="sidebar-note">${icon('leaf')}<h3>Un village.<br>Mille petits liens.</h3><p>Un trajet partagé, un outil prêté, un bon moment ensemble.</p></div><button class="reset-button" data-action="reset">${icon('refresh')}Réinitialiser la démo</button><p class="sidebar-footer">Imaginé pour Prémeyzel<br>Prototype communautaire · 2026</p></aside>
  <main id="main" tabindex="-1">${storageWarning?`<div class="notice warning" role="alert">${esc(storageWarning)}</div>`:''}${!navigator.onLine?'<div class="notice">Mode hors connexion · vos actions restent sur cet appareil.</div>':''}${renderPage(r)}</main></div>
  <nav class="mobile-nav" aria-label="Navigation mobile">${navs.map(([key,i,label])=>`<a href="#/${key}" ${r===key?'aria-current="page"':''} class="${r===key?'active':''}">${icon(i)}<span>${key==='annonces'?'Annonces':key==='accueil'?'Village':label}</span></a>`).join('')}</nav>`;
}
function renderPage(r){if(['trajets','annonces','messages','activite','notifications'].includes(r)&&!current())return gated();switch(r){case'evenements':return eventsPage();case'trajets':return tripsPage();case'annonces':return adsPage();case'balades':return trailsPage();case'messages':return messagesPage();case'activite':return activityPage();case'notifications':return notificationsPage();case'admin':return adminPage();default:return homePage();}}
function sectionHeading(title,description,href,label='Tout voir'){return `<div class="section-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div><a class="text-link" href="#/${href}">${label} ${icon('arrow')}</a></div>`;}
function homePage(){
  const events=state.events.filter(activePost).sort((a,b)=>a.date.localeCompare(b.date));
  return `<section class="hero"><div class="hero-copy"><span class="hero-label">${icon('pin')} AIN · BUGEY SUD</span><h1>La vie est plus belle<br><em>entre voisins.</em></h1><p>Se retrouver, s’entraider, partager.<br>Les petites choses qui font notre village.</p>${publishButton('Partager quelque chose') }<span class="hero-footnote">Bienvenue ${current()?esc(current().short):'à Prémeyzel'} ${icon('sun')}</span></div><div class="hero-art">${villageArt()}<span class="art-caption">Notre coin de nature, notre coin de vie.</span></div></section>
  <div class="quick-links">${[['evenements','calendar','On se retrouve ?','Les rendez-vous du village'],['trajets','car','On fait un bout de chemin ?','Trajets & courses partagés'],['annonces','tag','Ça peut servir !','Donner, louer, prêter, échanger'],['balades','trail','On prend l’air ?','À pied ou à vélo']].map(([href,i,title,sub])=>`<a href="#/${href}" class="quick-link"><span class="quick-icon ${href}">${icon(i)}</span><span><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</a>`).join('')}</div>
  ${sectionHeading('Bientôt, au village','Des occasions de se retrouver.','evenements','Voir l’agenda')}<div class="event-grid">${events.slice(0,3).map(eventCard).join('')||empty('L’agenda attend vos idées','Proposez le prochain rendez-vous.',publishButton('Créer un événement','events'))}</div>
  <div class="home-bottom"><section>${sectionHeading('Les petits coups de main','Tout commence par un voisin.','annonces')}<div class="compact-ads">${current()?state.ads.filter(activePost).slice(0,3).map(p=>`<button class="compact-ad" data-action="detail" data-type="ads" data-id="${p.id}"><span class="mini-art">${postVisual(p,'ads')}</span><span>${badge(p.category)}<strong>${esc(p.title)}</strong><small>${esc(p.price)}</small></span>${icon('chevron')}</button>`).join(''):`<div class="member-teaser">${icon('users')}<h3>Les bonnes idées circulent.</h3><p>Découvrez les annonces et les trajets avec un profil habitant.</p><button class="btn secondary" data-action="profiles">Choisir un profil</button></div>`}</div></section><a class="nature-panel" href="#/balades"><div>${badge('L’ENVIE DU MOMENT')}<h2>Et si on prenait<br>le chemin des écoliers ?</h2><p>Découvrez les balades de la démo.</p><span class="text-link">Explorer les parcours ${icon('arrow')}</span></div>${cardArt('forest')}</a></div>
  <div class="home-end">${icon('leaf')}Les grands liens commencent par de petits gestes.</div>`;
}
function searchBar(placeholder){return `<div class="search-box">${icon('search')}<input type="search" id="search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(query)}" autocomplete="off">${query?'<button class="icon-button" data-action="clear-search" aria-label="Effacer la recherche">'+icon('close')+'</button>':''}</div>`;}
function filterChips(values){return `<div class="filters" aria-label="Filtres">${values.map(v=>`<button class="chip ${filter===v?'selected':''}" data-action="filter" data-value="${esc(v)}" aria-pressed="${filter===v}">${esc(v)}</button>`).join('')}</div>`;}
function eventCard(p){const used=eventUsed(state,p.id),remaining=p.capacity?p.capacity-used:null;return `<article class="card event-card"><button class="card-image" data-action="detail" data-type="events" data-id="${p.id}" aria-label="Voir ${esc(p.title)}">${postVisual(p,'events')}<span class="date-stamp"><strong>${dateText(p.date,{day:'numeric'})}</strong><span>${dateText(p.date,{month:'short'})}</span></span></button><div class="card-body">${badge(p.category||'Rencontre','plain')}<h3><button class="title-button" data-action="detail" data-type="events" data-id="${p.id}">${esc(p.title)}</button></h3><p class="meta">${icon('clock')}${esc(dateText(p.date))} · ${timeText(p.date)}</p><p class="meta">${icon('pin')}${esc(p.location)}</p><div class="card-footer"><span class="availability ${remaining===0?'full':''}"><span></span>${remaining===null?'Ouvert à tous':remaining===0?'Liste d’attente':`${remaining} places disponibles`}</span><button class="round-button" data-action="detail" data-type="events" data-id="${p.id}" aria-label="Détails de ${esc(p.title)}">${icon('arrow')}</button></div></div></article>`;}
function eventsPage(){const posts=state.events.filter(activePost).filter(matches).filter(p=>filter==='Tout'||p.category===filter).sort((a,b)=>a.date.localeCompare(b.date));return `${pageTitle('SE RETROUVER','Les rendez-vous du village','Un atelier, une fête, un moment à partager.',publishButton('Proposer un événement','events'))}${searchBar('Rechercher un événement…')}${filterChips(['Tout',...new Set(state.events.filter(activePost).map(p=>p.category||'Rencontre'))])}<p class="results-count">${posts.length} rendez-vous à découvrir</p><div class="event-grid">${posts.map(eventCard).join('')}</div>${!posts.length?empty('Aucun événement pour le moment','Essayez une autre recherche ou proposez votre idée.'):''}`;}
function tripCard(t){const left=t.capacity-tripUsed(state,t.id);const own=state.bookings.find(b=>b.tripId===t.id&&b.userId===state.profile&&['confirmed','pending'].includes(b.status));return `<article class="trip-card"><div class="trip-date"><strong>${dateText(t.date,{day:'numeric',month:'short'})}</strong><span>${dateText(t.date,{weekday:'long'})}</span><b>${timeText(t.date)}</b></div><div class="trip-main"><div class="trip-badges">${badge(t.kind==='request'?'Recherche un trajet':t.kind==='errand'?'Courses partagées':'Propose un trajet',t.kind==='request'?'amber':'')}${t.recurring?`<span class="recurring">${icon('repeat')}Chaque semaine</span>`:''}${mine(t)?badge('Votre trajet','plain'):''}</div><h3><button class="title-button" data-action="detail" data-type="trips" data-id="${t.id}">${esc(t.from)} ${icon('arrow')} ${esc(t.to)}</button></h3><p>${esc(t.description)}</p>${author(t)}</div><div class="trip-end">${own?badge(statusText[own.status],own.status==='pending'?'amber':''):t.kind!=='request'?`<strong>${icon('users')}${left} place${left>1?'s':''}</strong>`:''}<button class="btn ${t.kind==='request'?'secondary':'primary'}" data-action="detail" data-type="trips" data-id="${t.id}">${mine(t)?'Gérer':own?'Ma demande':t.kind==='request'?'Proposer mon aide':'Voir le trajet'}</button></div></article>`;}
function tripsPage(){const posts=state.trips.filter(activePost).filter(matches).filter(t=>filter==='Tout'||(filter==='Propositions'&&t.kind==='offer')||(filter==='Recherches'&&t.kind==='request')||(filter==='Courses partagées'&&t.kind==='errand')).sort((a,b)=>a.date.localeCompare(b.date));return `${pageTitle('FAIRE UN BOUT DE CHEMIN','Un trajet, un voisin.','Une place libre ou quelques courses : partageons le chemin.',publishButton('Publier un trajet','trips'))}<div class="notice soft">${icon('info')}Les demandes de places sont confirmées par le conducteur. Les courses peuvent aussi s’organiser par message.</div>${searchBar('Rechercher une destination, un trajet…')}${filterChips(['Tout','Propositions','Recherches','Courses partagées'])}<p class="results-count">${posts.length} départs et demandes</p><div class="trip-list">${posts.map(tripCard).join('')}</div>${!posts.length?empty('Pas de trajet trouvé','Publiez votre demande : un voisin fait peut-être le même chemin.'):''}`;}
function adCard(p){return `<article class="card ad-card"><button class="card-image" data-action="detail" data-type="ads" data-id="${p.id}" aria-label="Voir ${esc(p.title)}">${postVisual(p,'ads')}<span class="image-badge">${badge(p.category,p.category==='À louer'?'amber':'')}</span></button><div class="card-body"><div class="price">${esc(p.price||'À convenir')}</div><h3><button class="title-button" data-action="detail" data-type="ads" data-id="${p.id}">${esc(p.title)}</button></h3><p class="ad-excerpt">${esc(p.description)}</p><div class="card-footer">${author(p)}<button class="round-button" data-action="detail" data-type="ads" data-id="${p.id}" aria-label="Détails de ${esc(p.title)}">${icon('arrow')}</button></div></div></article>`;}
function adsPage(){const posts=state.ads.filter(activePost).filter(matches).filter(p=>filter==='Tout'||p.category===filter);return `${pageTitle('ÇA PEUT SERVIR','Les petites annonces','À donner, à louer, à prêter… et tellement à partager.',publishButton('Déposer une annonce','ads'))}${searchBar('Rechercher un objet, un service, une idée…')}${filterChips(AD_CATEGORIES)}<p class="results-count">${posts.length} annonces entre voisins</p><div class="ad-grid">${posts.map(adCard).join('')}</div>${!posts.length?empty('Rien ici pour le moment','Essayez une autre catégorie ou publiez la première annonce.'):''}`;}
function trailsPage(){const posts=state.trails.filter(activePost).filter(matches).filter(p=>filter==='Tout'||p.activity===filter||(filter==='Favoris'&&state.favorites.includes(`${state.profile}:${p.id}`)));let selected=posts.find(p=>p.id===selectedTrail)||posts[0];if(selected)selectedTrail=selected.id;return `${pageTitle('PRENDRE L’AIR','Autour de chez nous','À pied ou à VTT, le plaisir d’explorer ensemble.',publishButton('Proposer une balade','trails'))}<div class="notice warning">${icon('info')}Parcours fictifs · carte illustrative. Ne pas utiliser pour vous orienter ou vous déplacer.</div>${searchBar('Rechercher une balade…')}${filterChips(['Tout','Marche','VTT',...(current()?['Favoris']:[])])}<div class="trails-layout"><div class="trail-list">${posts.map(p=>`<article class="trail-card ${selectedTrail===p.id?'selected':''}"><button class="trail-select" data-action="select-trail" data-id="${p.id}" aria-pressed="${selectedTrail===p.id}"><span class="trail-icon">${icon(p.activity==='VTT'?'bike':'walk')}</span><span>${badge(p.difficulty,'plain')}<h3>${esc(p.title)}</h3><span class="trail-stats">${p.distance} km · ${Math.floor(p.duration/60)}h${String(p.duration%60).padStart(2,'0')} · +${p.elevation} m</span></span></button><div class="trail-actions"><button class="text-link" data-action="detail" data-type="trails" data-id="${p.id}">Voir la fiche ${icon('arrow')}</button>${current()?`<button class="icon-button ${state.favorites.includes(`${state.profile}:${p.id}`)?'favorited':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(`${state.profile}:${p.id}`)?'Retirer des':'Ajouter aux'} favoris" aria-pressed="${state.favorites.includes(`${state.profile}:${p.id}`)}">${icon('heart')}</button>`:''}</div></article>`).join('')||empty('Aucun parcours trouvé','Modifiez votre recherche ou votre filtre.')}</div><div class="map-panel"><div class="map-canvas">${mapArt(selected?.route??0,zoom)}<div class="map-controls"><button class="icon-button" data-action="zoom" data-value="1" aria-label="Agrandir la carte">${icon('plus')}</button><button class="icon-button" data-action="zoom" data-value="-1" aria-label="Réduire la carte">${icon('minus')}</button><button class="icon-button" data-action="zoom" data-value="0" aria-label="Recentrer la carte">${icon('refresh')}</button></div><span class="map-label">PLAN ILLUSTRATIF · DÉMO</span></div><div class="map-caption"><span class="route-dot"></span><strong>${esc(selected?.title||'Sélectionnez un parcours')}</strong><small>Tracés fictifs · sans navigation</small></div></div></div>`;}
function messagesPage(){const conversations=state.conversations.filter(c=>c.participants.includes(state.profile));let active=conversations.find(c=>c.id===activeConversation)||conversations[0];activeConversation=active?.id;return `${pageTitle('GARDER LE LIEN','Mes messages','Des conversations privées entre profils de démonstration.')}<div class="messages-layout"><div class="conversation-list">${conversations.map(c=>{const other=c.participants.find(id=>id!==state.profile);return `<button class="conversation ${active?.id===c.id?'selected':''}" data-action="conversation" data-id="${c.id}">${avatar(other)}<span><strong>${esc(person(other).short)}</strong><small>${esc(c.subject)}</small><span>${esc(c.messages.at(-1)?.text||'Commencez la conversation')}</span></span></button>`;}).join('')||empty('Aucune conversation','Contactez un voisin depuis une annonce ou un trajet.')}</div><section class="chat-panel">${active?`<header>${avatar(active.participants.find(id=>id!==state.profile))}<div><h2>${esc(person(active.participants.find(id=>id!==state.profile)).name)}</h2><p>${esc(active.subject)}</p></div></header><div class="chat-messages">${active.messages.map(m=>`<div class="message ${m.sender===state.profile?'mine':''}"><p>${esc(m.text)}</p><small>${esc(person(m.sender).short)} · ${timeText(m.date)}</small></div>`).join('')||'<p class="fine">Écrivez le premier message.</p>'}</div><form id="message-form"><label class="sr-only" for="message-text">Votre message</label><textarea id="message-text" name="text" rows="2" maxlength="2000" required placeholder="Écrivez à votre voisin…"></textarea><button class="btn primary" type="submit" aria-label="Envoyer le message">${icon('arrow')}</button></form><p class="chat-footnote">Pour tester une réponse, passez sur le profil de votre interlocuteur.</p>`:empty('Un petit bonjour ?','Vos échanges avec les voisins apparaîtront ici.')}</section></div>`;}
function activityPage(){const registrations=state.registrations.filter(r=>r.userId===state.profile),bookings=state.bookings.filter(b=>b.userId===state.profile);const owned=Object.keys(collectionFor).flatMap(key=>state[collectionFor[key]].filter(p=>p.owner===state.profile&&!p.deleted).map(p=>({...p,collection:collectionFor[key]})));const incoming=state.bookings.filter(b=>b.status==='pending'&&state.trips.some(t=>t.id===b.tripId&&t.owner===state.profile&&!t.deleted));return `${pageTitle('MON COIN DU VILLAGE','Mon activité','Vos participations, vos trajets et vos publications.')} ${incoming.length?`<section class="activity-section"><h2>Demandes de places à confirmer ${badge(incoming.length,'amber')}</h2>${incoming.map(b=>{const t=state.trips.find(t=>t.id===b.tripId);return `<div class="activity-row"><div><strong>${esc(person(b.userId).short)} · ${b.seats} place(s)</strong><span>${esc(t.title)} · ${dateText(t.date)} à ${timeText(t.date)}</span></div><button class="btn secondary" data-action="detail" data-type="trips" data-id="${t.id}">Répondre</button></div>`;}).join('')}</section>`:''}<section class="activity-section"><h2>Mes inscriptions & demandes</h2>${[...registrations.map(r=>({r,p:state.events.find(e=>e.id===r.eventId),collection:'events',count:r.count})),...bookings.map(r=>({r,p:state.trips.find(t=>t.id===r.tripId),collection:'trips',count:r.seats}))].map(({r,p,collection,count})=>`<div class="activity-row"><span class="activity-symbol">${icon(collection==='events'?'calendar':'car')}</span><div><strong>${esc(p?.title||'Publication retirée')}</strong><span>${p?dateText(p.date):''} · ${count} place(s)</span></div>${badge(statusText[r.status],['pending','waiting'].includes(r.status)?'amber':'')}${p&&!p.deleted?`<button class="btn small secondary" data-action="detail" data-type="${collection}" data-id="${p.id}">Voir</button>`:''}</div>`).join('')||empty('Votre agenda est encore libre','Un événement ou un trajet vous attend peut-être.')}</section><section class="activity-section"><div class="section-heading"><h2>Mes publications</h2>${publishButton()}</div>${owned.map(p=>`<div class="activity-row"><div><strong>${esc(p.title)}</strong><span>${{events:'Événement',trips:'Trajet',ads:'Annonce',trails:'Balade'}[p.collection]}</span></div><button class="btn small secondary" data-action="detail" data-type="${p.collection}" data-id="${p.id}">Gérer</button></div>`).join('')||empty('Une idée à partager ?','Votre première publication apparaîtra ici.')}</section>`;}
function notificationsPage(){const notes=state.notifications.filter(n=>n.userId===state.profile);return `${pageTitle('LES NOUVELLES','Mes notifications','Demandes, confirmations et changements de programme.',notes.length?'<button class="btn secondary" data-action="read-notifications">Tout marquer comme lu</button>':'')}<div class="notification-list">${notes.map(n=>`<article class="notification ${n.read?'':'unread'}"><span>${icon('bell')}</span><div><p>${esc(n.text)}</p><small>${dateText(n.date)} · ${timeText(n.date)}</small></div>${!n.read?'<span class="unread-dot" aria-label="Non lue"></span>':''}</article>`).join('')||empty('Tout est calme','Les nouvelles concernant vos activités apparaîtront ici.')}</div>`;}
function adminPage(){if(!current()?.admin)return gated();const reports=state.reports.filter(r=>!r.resolved);return `${pageTitle('PRENDRE SOIN DU VILLAGE','Administration','Publier, modifier, retirer une publication et traiter les signalements.',publishButton())}<div class="admin-stats">${[['events','Événements'],['trips','Trajets'],['ads','Annonces'],['trails','Balades']].map(([k,l])=>`<div><strong>${state[k].filter(activePost).length}</strong><span>${l}</span></div>`).join('')}</div><section class="activity-section"><h2>Signalements à examiner ${badge(reports.length,'amber')}</h2>${reports.map(r=>{const p=state[r.collection].find(p=>p.id===r.postId);return `<div class="report"><p><strong>${esc(p?.title||'Publication retirée')}</strong> · signalé par ${esc(person(r.userId).short)}</p><p>${esc(r.reason)}</p><div class="button-row">${p&&!p.deleted?`<button class="btn secondary small" data-action="detail" data-type="${r.collection}" data-id="${p.id}">Examiner</button>`:''}<button class="btn secondary small" data-action="resolve-report" data-id="${r.id}">Marquer comme traité</button></div></div>`;}).join('')||'<p class="fine">Aucun signalement en attente.</p>'}</section><section class="activity-section"><h2>Toutes les publications</h2>${['events','trips','ads','trails'].flatMap(k=>state[k].filter(activePost).map(p=>`<div class="activity-row"><div><strong>${esc(p.title)}</strong><span>${esc(person(p.owner).name)} · ${{events:'Événement',trips:'Trajet',ads:'Annonce',trails:'Balade'}[k]}</span></div><button class="btn secondary small" data-action="detail" data-type="${k}" data-id="${p.id}">Gérer</button></div>`)).join('')}</section>`;}

function showDialog(title,content,wide=false){photoDraft=null;focusBeforeDialog=document.activeElement;$('#modal-root').innerHTML=`<dialog class="modal ${wide?'wide':''}" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></header><div class="modal-body">${content}</div></dialog>`;const d=$('dialog');d.showModal();d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog();}});d.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});}
function closeDialog(){photoDraft=null;const d=$('dialog');if(d)d.close();$('#modal-root').innerHTML='';if(focusBeforeDialog?.isConnected)focusBeforeDialog.focus();}
function errors(){return '<p class="form-error" id="form-error" role="alert" tabindex="-1"></p>';}
function management(p,type){if(!current())return '';return `<div class="management">${canEdit(state.profile,p)?`<button class="text-link" data-action="edit" data-type="${type}" data-id="${p.id}">${icon('edit')}Modifier</button><button class="text-link danger" data-action="delete" data-type="${type}" data-id="${p.id}">${icon('trash')}Supprimer</button>`:`<button class="text-link muted" data-action="report" data-type="${type}" data-id="${p.id}">${icon('flag')}Signaler cette publication</button>`}</div>`;}
function contactButton(p,label='Contacter le voisin'){return current()&&!mine(p)?`<button class="btn secondary" data-action="contact" data-id="${p.id}" data-owner="${p.owner}" data-title="${esc(p.title)}">${icon('chat')}${label}</button>`:'';}
function detail(type,id){
  if(!current()&&['ads','trips'].includes(type)){profilesDialog();return;}
  const p=state[type]?.find(p=>p.id===id&&!p.deleted);if(!p){toast('Cette publication n’est plus disponible.');return;}
  let extra='';
  if(type==='events'){
    const reg=state.registrations.find(r=>r.eventId===id&&r.userId===state.profile&&['confirmed','waiting'].includes(r.status));const used=eventUsed(state,id);
    extra=`<div class="detail-facts"><span>${icon('calendar')}${longDate(p.date)} · ${timeText(p.date)}</span><span>${icon('users')}${p.capacity?`${used} / ${p.capacity} places réservées`:'Sans limite de places'}</span></div>`;
    if(p.registrationNote)extra+=`<div class="notice">${icon('info')}<span>${esc(p.registrationNote)}</span></div>`;
    if(mine(p)){const regs=state.registrations.filter(r=>r.eventId===id&&['confirmed','waiting'].includes(r.status));extra+=`<div class="booking-box"><h3>Les participants</h3>${regs.map(r=>`<div class="participant">${avatar(r.userId,true)}<span>${esc(person(r.userId).name)} · ${r.count} place(s)</span>${badge(statusText[r.status],r.status==='waiting'?'amber':'')}</div>`).join('')||'<p>Aucune inscription pour le moment.</p>'}</div>`;}
    else if(reg)extra+=`<div class="booking-box"><h3>Votre inscription</h3><p>${reg.count} place(s) · ${badge(statusText[reg.status],reg.status==='waiting'?'amber':'')}</p><button class="btn secondary" data-action="cancel-registration" data-id="${reg.id}">Annuler mon inscription</button></div>`;
    else if(current())extra+=`<form class="booking-box" id="registration-form" data-id="${id}"><h3>On vous garde une place ?</h3><p>Inscrivez votre foyer ensemble. Si l’événement est complet, vous rejoindrez la liste d’attente.</p><div class="inline-form"><label>Nombre de personnes<input type="number" name="count" min="1" max="${p.capacity||50}" value="1" required></label><button class="btn primary" type="submit">M’inscrire ${icon('arrow')}</button></div>${errors()}</form>`;
    else extra+='<button class="btn primary" data-action="profiles">Choisir un profil pour participer</button>';
  }
  if(type==='trips'){
    const b=state.bookings.find(b=>b.tripId===id&&b.userId===state.profile&&['pending','confirmed'].includes(b.status));
    extra=`<div class="detail-facts"><span>${icon('calendar')}${longDate(p.date)} · ${timeText(p.date)}</span><span>${icon('car')}${esc(p.from)} → ${esc(p.to)}</span>${p.kind!=='request'?`<span>${icon('users')}${p.capacity-tripUsed(state,id)} place(s) disponible(s)</span>`:''}${p.recurring?`<span>${icon('repeat')}Rendez-vous hebdomadaire · chaque départ se réserve séparément</span>`:''}</div>`;
    if(mine(p)&&p.kind!=='request'){const bs=state.bookings.filter(b=>b.tripId===id&&['pending','confirmed'].includes(b.status));extra+=`<div class="booking-box"><h3>Demandes pour ce départ</h3>${bs.map(b=>`<div class="booking-request"><p><strong>${esc(person(b.userId).name)}</strong> · ${b.seats} place(s) ${badge(statusText[b.status],b.status==='pending'?'amber':'')}</p>${b.status==='pending'?`<div class="button-row"><button class="btn primary small" data-action="decide-booking" data-id="${b.id}" data-value="accept">Accepter</button><button class="btn secondary small" data-action="decide-booking" data-id="${b.id}" data-value="decline">Refuser</button></div>`:''}</div>`).join('')||'<p>Aucune demande pour le moment.</p>'}</div>`;}
    else if(b)extra+=`<div class="booking-box"><h3>Votre demande</h3><p>${b.seats} place(s) · ${badge(statusText[b.status],b.status==='pending'?'amber':'')}</p><button class="btn secondary" data-action="cancel-booking" data-id="${b.id}">Annuler ma demande</button></div>`;
    else if(!mine(p)&&p.kind!=='request'&&p.capacity-tripUsed(state,id)>0)extra+=`<form id="booking-form" class="booking-box" data-id="${id}"><h3>Partageons le trajet</h3><p>Le conducteur confirmera votre demande. Aucune place n’est réservée avant son accord.</p><div class="inline-form"><label>Nombre de places<input name="seats" type="number" min="1" max="${p.capacity-tripUsed(state,id)}" value="1" required></label><button class="btn primary" type="submit">Demander ${icon('arrow')}</button></div>${errors()}</form>`;
    else if(!mine(p)&&p.kind!=='request')extra+='<div class="notice">Ce départ est complet.</div>';
    extra+=contactButton(p,p.kind==='request'?'Proposer mon aide par message':'Échanger avec le voisin');
  }
  if(type==='ads'){extra=`<div class="detail-price">${esc(p.price||'À convenir')}</div>${p.category==='À louer'?'<p class="fine">Précisez ensemble les dates, la durée, le prix et les conditions de location par message.</p>':''}${contactButton(p,'Ça m’intéresse · envoyer un message')}<p class="fine">Accord et paiement éventuel à organiser entre vous. Aucun paiement dans la démo.</p>`;}
  if(type==='trails')extra=`<div class="detail-facts"><span>${icon(p.activity==='VTT'?'bike':'walk')}${p.activity} · ${p.difficulty}</span><span>${icon('trail')}${p.distance} km · +${p.elevation} m</span><span>${icon('clock')}${p.duration} minutes</span></div><div class="notice warning">Parcours fictif. Ne pas utiliser pour la navigation.</div><div class="detail-map">${mapArt(p.route||0)}</div>`;
  const art=`<div class="detail-art">${postVisual(p,type)}</div>`;
  showDialog(p.title,`${art}<div class="detail-top">${badge(p.category||p.activity||(p.kind==='request'?'Recherche un trajet':'Trajet partagé'))}${author(p)}</div><p class="detail-description">${esc(p.description)}</p><p class="meta">${icon('pin')}${esc(p.location)}</p>${extra}${management(p,type)}`,true);
}
function profilesDialog(){showDialog('Essayez la vie du village',`<p>Choisissez un rôle pour tester la démo. Ces profils servent uniquement à tester les publications et les échanges ; le changement de rôle ne constitue pas une connexion sécurisée.</p><div class="profile-shortcuts">${current()?'<a class="btn secondary" href="#/activite">Mon activité</a>':''}${current()?.admin?'<a class="btn secondary" href="#/admin">Administration</a>':''}<button class="btn secondary" data-action="install">Installer</button><button class="btn secondary" data-action="reset">Réinitialiser</button></div><div class="profile-choices">${[...PEOPLE,{id:'guest',name:'Visiteur',short:'Visiteur'}].map(p=>`<button class="profile-choice ${state.profile===p.id?'chosen':''}" data-action="set-profile" data-id="${p.id}">${avatar(p.id)}<span><strong>${esc(p.name)}</strong><small>${p.admin?'Gérer les publications et les signalements':p.id==='guest'?'Parcourir les événements et les balades':'Publier, participer, réserver et échanger'}</small></span>${state.profile===p.id?icon('check'):icon('chevron')}</button>`).join('')}</div><p class="fine">Les modifications restent sur cet appareil. Aucun compte réel n’est créé.</p>`);}
function input(label,name,value='',type='text',attrs=''){return `<label><span class="field-label">${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,values,value){
  const options=values.map(v=>Array.isArray(v)?v:[v,v]);
  const selected=options.find(([val])=>val===value)||options[0];
  return `<label><span class="field-label">${esc(label)}</span><span class="select-control"><select name="${esc(name)}">${options.map(([val,text])=>`<option value="${esc(val)}" ${val===selected[0]?'selected':''}>${esc(text)}</option>`).join('')}</select><span class="select-value" aria-hidden="true">${esc(selected[1])}</span></span></label>`;
}
function compose(type='',id=''){
  if(!current()){profilesDialog();return;}
  if(!type){showDialog('Qu’aimeriez-vous partager ?',`<p>Une idée, une place libre ou un objet qui peut servir : c’est à vous.</p><div class="compose-choices">${[['events','calendar','Un événement','Se retrouver et participer'],['trips','car','Un trajet','Proposer, chercher ou partager des courses'],['ads','tag','Une petite annonce','Donner, louer, prêter, échanger…'],['trails','trail','Une balade','Partager un parcours de démonstration']].map(([t,i,title,desc])=>`<button data-action="compose" data-type="${t}">${icon(i)}<span><strong>${title}</strong><small>${desc}</small></span>${icon('chevron')}</button>`).join('')}</div>`);return;}
  if(!['events','trips','ads','trails'].includes(type))return;
  const p=id?state[type].find(p=>p.id===id):{};if(!p||(id&&!canEdit(state.profile,p)))return;
  let fields='';
  if(type==='events')fields=`${select('Type de rendez-vous','category',['Rencontre','Convivialité','Atelier','Sport','Culture'],p.category||'Rencontre')}<div class="form-grid">${input('Date','date',(p.date||dateAfter(7)).slice(0,10),'date','required')}${input('Heure (facultative)','eventTime',p.date?.split('T')[1]||'','time')}${input('Capacité (0 = sans limite)','capacity',p.capacity??20,'number','min="0" max="500" required')}</div>`;
  if(type==='trips')fields=`${select('Votre publication','kind',[['offer','Je propose des places'],['request','Je cherche un trajet'],['errand','Je propose des courses partagées']],p.kind||'offer')}<div class="form-grid">${input('Départ','from',p.from||'Prémeyzel','text','required maxlength="80"')}${input('Destination','to',p.to||'','text','required maxlength="80"')}${input('Date et heure du départ','date',p.date||dateAfter(1,'08:00'),'datetime-local','required')}${input('Places proposées / recherchées','capacity',p.capacity??2,'number','min="1" max="8" required')}</div>${id?`<p class="fine">Vous modifiez uniquement ce départ${p.series?' de la série hebdomadaire':''}.</p>`:'<label class="checkbox"><input type="checkbox" name="recurring">Chaque semaine · créer 4 départs au même jour et à la même heure</label>'}`;
  if(type==='ads')fields=`<div class="form-grid">${select('Catégorie','category',AD_CATEGORIES.slice(1),p.category||'À louer')}${input('Prix ou contrepartie','price',p.price||'','text','maxlength="80" placeholder="Ex. 15 € / jour, gratuit, troc…"')}</div><p class="fine">Pour une location, indiquez le tarif et sa durée. Convenez des disponibilités et des conditions par message.</p>`;
  if(type==='trails')fields=`<div class="notice warning">Chaque parcours de ce prototype est fictif. Choisissez un tracé illustratif, sans usage de navigation.</div><div class="form-grid">${select('Activité','activity',['Marche','VTT'],p.activity||'Marche')}${select('Difficulté','difficulty',['Facile','Modéré','Sportif'],p.difficulty||'Facile')}${input('Distance (km)','distance',p.distance??4.2,'number','min="0.1" max="1000" step="0.1" required')}${input('Durée (minutes)','duration',p.duration??60,'number','min="1" max="10000" step="1" required')}${input('Dénivelé positif (m)','elevation',p.elevation??90,'number','min="0" max="10000" step="1" required')}${select('Tracé de démonstration','route',[['0','Boucle des vergers'],['1','Boucle des sous-bois'],['2','Boucle des crêtes']],String(p.route??0))}</div>`;
  showDialog(id?'Modifier la publication':{events:'Proposer un événement',trips:'Publier un trajet',ads:'Déposer une annonce',trails:'Proposer une balade'}[type],`<form id="post-form" data-type="${type}" data-id="${id}"><p class="fine">Publication immédiate · visible dans votre démonstration locale.</p>${input('Titre','title',p.title||'','text','required minlength="4" maxlength="100" placeholder="Un titre simple et précis"')}${fields}${input(type==='trips'?'Point de rendez-vous (approximatif)':'Lieu (approximatif)','location',p.location||'Prémeyzel','text','required maxlength="120"')}<label>Description<textarea name="description" rows="4" required minlength="10" maxlength="2000" placeholder="Racontez votre proposition et les détails utiles…">${esc(p.description||'')}</textarea></label>${photoEditor()}${errors()}<div class="form-footer"><button class="btn secondary" type="button" data-action="close">Annuler</button><button class="btn primary" type="submit">${id?'Enregistrer':'Publier'} ${icon('arrow')}</button></div></form>`,true);
  photoDraft={form:$('#post-form'),type,photo:p.photo||null,request:0,busy:false};updatePhotoEditor();
}
function deleteDialog(type,id){const p=state[type].find(p=>p.id===id);if(!p||!canEdit(state.profile,p))return;showDialog('Supprimer cette publication ?',`<p><strong>${esc(p.title)}</strong></p><p>${['events','trips'].includes(type)?'Les inscriptions et demandes concernées seront annulées. Les profils affectés recevront une notification dans la démo.':'La publication disparaîtra des listes. Les conversations existantes resteront accessibles à leurs participants.'}</p><form id="delete-form" data-type="${type}" data-id="${id}">${p.series?'<label class="checkbox"><input type="checkbox" name="series">Annuler tous les départs futurs de cette série</label>':''}${errors()}<div class="form-footer"><button type="button" class="btn secondary" data-action="close">Conserver</button><button type="submit" class="btn danger-fill">Confirmer la suppression</button></div></form>`);}

document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id,type,value}=b.dataset;
  if(a==='close')closeDialog();
  if(a==='remove-photo'&&photoDraft){photoDraft.request++;photoDraft.photo=null;photoDraft.busy=false;$('#post-photo').value='';$('#photo-error').textContent='';updatePhotoEditor();$('#post-photo').focus();}
  if(a==='profiles')profilesDialog();
  if(a==='set-profile'){state.profile=id;activeConversation=null;persist();closeDialog();render();toast(`Profil ${person(id)?.short||'visiteur'} activé.`);}
  if(a==='compose')compose(type);
  if(a==='edit')compose(type,id);
  if(a==='detail')detail(type,id);
  if(a==='filter'){filter=value;render();}
  if(a==='clear-search'){query='';render();$('#search')?.focus();}
  if(a==='select-trail'){selectedTrail=id;render();}
  if(a==='zoom'){zoom=Number(value)===0?1:Math.max(.75,Math.min(2,zoom+Number(value)*.25));render();}
  if(a==='favorite'){const key=`${state.profile}:${id}`;state.favorites=state.favorites.includes(key)?state.favorites.filter(k=>k!==key):[...state.favorites,key];persist();render();}
  if(a==='delete')deleteDialog(type,id);
  if(a==='cancel-registration'){const reg=state.registrations.find(r=>r.id===id);if(action(()=>cancelRegistration(state,state.profile,id)).ok){render();detail('events',reg.eventId);toast('Votre inscription a été annulée.');}}
  if(a==='cancel-booking'){const booking=state.bookings.find(r=>r.id===id);if(action(()=>cancelBooking(state,state.profile,id)).ok){render();detail('trips',booking.tripId);toast('Votre demande a été annulée.');}}
  if(a==='decide-booking'){const booking=state.bookings.find(r=>r.id===id);if(action(()=>decideBooking(state,state.profile,id,value==='accept')).ok){render();detail('trips',booking.tripId);toast(value==='accept'?'Demande acceptée.':'Demande refusée.');}}
  if(a==='contact'){showDialog('Un petit message au voisin',`<p>À ${esc(person(b.dataset.owner).short)} · ${esc(b.dataset.title)}</p><p class="fine">Message de démonstration uniquement : il reste dans ce navigateur et n’est pas transmis à cette personne.</p><form id="contact-form" data-id="${id}" data-owner="${b.dataset.owner}" data-title="${esc(b.dataset.title)}"><label>Votre message<textarea name="text" rows="4" required maxlength="2000" placeholder="Bonjour, votre proposition m’intéresse…"></textarea></label>${errors()}<div class="form-footer"><button class="btn primary" type="submit">Envoyer le message ${icon('arrow')}</button></div></form>`);}
  if(a==='conversation'){activeConversation=id;render();}
  if(a==='report'){showDialog('Signaler une publication',`<p>Le signalement sera transmis au profil admin. La publication reste visible pendant son examen.</p><form id="report-form" data-type="${type}" data-id="${id}"><label>Pourquoi la signalez-vous ?<textarea name="reason" rows="3" maxlength="1000" required></textarea></label>${errors()}<div class="form-footer"><button class="btn primary" type="submit">Envoyer le signalement</button></div></form>`);}
  if(a==='resolve-report'&&action(()=>resolveReport(state,state.profile,id)).ok){render();toast('Signalement marqué comme traité.');}
  if(a==='read-notifications'){state.notifications.filter(n=>n.userId===state.profile).forEach(n=>n.read=true);persist();render();}
  if(a==='reset')showDialog('Repartir de zéro ?',`<p>Les publications, photos, réservations et messages ajoutés sur cet appareil seront remplacés par les exemples de départ.</p><div class="form-footer"><button class="btn secondary" data-action="close">Conserver mes essais</button><button class="btn danger-fill" data-action="confirm-reset">Réinitialiser la démo</button></div>`);
  if(a==='confirm-reset'){state=seed();query='';filter='Tout';activeConversation=null;persist();closeDialog();render();toast('La démonstration est prête pour un nouvel essai.');}
  if(a==='about')showDialog('Un village à essayer',`<div class="about-icon">${icon('leaf')}</div><p>Ce prototype imagine un espace d’entraide pour les habitants de Prémeyzel : événements, trajets, annonces et balades.</p><ul class="about-list"><li><strong>Un pilote à tester.</strong> Des exemples fictifs côtoient des publications proposées pour le village. Les profils sont simulés ; aucune inscription, commande ni message n’est transmis aux personnes citées. Les parcours restent fictifs.</li><li><strong>Vos essais restent ici.</strong> Les modifications sont enregistrées dans ce navigateur. Les autres appareils ne les voient pas.</li><li><strong>Changez de point de vue.</strong> Passez d’Alice à Lucas pour répondre à un message ou accepter une demande, puis à Camille pour tester l’administration.</li><li><strong>Recommencez à volonté.</strong> Le bouton de réinitialisation recharge les exemples.</li></ul><p class="fine">Prototype indépendant, sans affiliation officielle à la mairie. N’utilisez pas de données personnelles réelles dans la démo.</p>`);
  if(a==='install'){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>{deferredInstall=null;});}else showDialog('Prémeyzel à portée de main',`<p>Ajoutez le village à votre écran d’accueil pour le retrouver comme une application.</p><ol class="about-list"><li><strong>Sur iPhone ou iPad :</strong> ouvrez ce site dans Safari, touchez Partager, puis « Sur l’écran d’accueil ».</li><li><strong>Sur Android :</strong> ouvrez le menu du navigateur, puis « Installer l’application » ou « Ajouter à l’écran d’accueil ».</li><li><strong>Sur ordinateur :</strong> utilisez l’option d’installation de votre navigateur lorsqu’elle est proposée.</li></ol><p class="fine">Après une première visite complète, le prototype peut s’ouvrir hors connexion. Les données de chaque navigateur restent indépendantes.</p>`);}
});
// Preserve native select semantics while letting long visible values wrap.
document.addEventListener('error',e=>{if(e.target.matches?.('img.post-photo'))e.target.remove();},true);
document.addEventListener('change',e=>{
  if(e.target.id==='post-photo')uploadPhoto(e.target);
  if(e.target instanceof HTMLSelectElement){
    const value=e.target.parentElement.querySelector('.select-value');
    if(value)value.textContent=e.target.selectedOptions[0]?.textContent||'';
  }
});
document.addEventListener('pointerdown',e=>{
  if(e.button!==0||!(e.target instanceof Element))return;
  const select=e.target.closest('select')||e.target.closest('label')?.control;
  if(select instanceof HTMLSelectElement)select.dataset.pointerFocus='true';
},true);
document.addEventListener('keydown',e=>{
  if(!['Shift','Control','Alt','Meta','CapsLock'].includes(e.key))
    document.querySelectorAll('select[data-pointer-focus]').forEach(select=>delete select.dataset.pointerFocus);
},true);
document.addEventListener('focusout',e=>{
  if(e.target instanceof HTMLSelectElement)delete e.target.dataset.pointerFocus;
},true);
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();const input=$('#search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',e=>{
  const f=e.target;if(!['post-form','registration-form','booking-form','message-form','contact-form','report-form','delete-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f)),{type,id}=f.dataset;
  if(f.id==='post-form'){if(photoDraft?.busy)return;data.photo=photoDraft?.photo||null;data.recurring=!!data.recurring;if(id)delete data.recurring;if(data.route!==undefined)data.route=Number(data.route);const result=action(()=>{state=savePostLocally(state,state.profile,type,data,id,localStorage);storageWarning='';});if(result.ok){closeDialog();const path=Object.keys(collectionFor).find(k=>collectionFor[k]===type);query='';filter='Tout';location.hash=`#/${path}`;render();toast(id?'Publication mise à jour.':data.recurring?'Quatre départs hebdomadaires publiés.':'Votre publication est en ligne dans la démo.');}}
  if(f.id==='registration-form'){const r=action(()=>registerEvent(state,state.profile,id,data.count));if(r.ok){render();detail('events',id);toast(r.result==='waiting'?'Votre groupe a rejoint la liste d’attente.':'Votre inscription est confirmée.');}}
  if(f.id==='booking-form'&&action(()=>bookTrip(state,state.profile,id,data.seats)).ok){render();detail('trips',id);toast('Demande envoyée au conducteur.');}
  if(f.id==='message-form'&&action(()=>sendMessage(state,state.profile,activeConversation,data.text)).ok){render();$('#message-text')?.focus();const messages=$('.chat-messages');if(messages)messages.scrollTop=messages.scrollHeight;}
  if(f.id==='contact-form'){const r=action(()=>startConversation(state,state.profile,f.dataset.owner,id,f.dataset.title,data.text));if(r.ok){activeConversation=r.result.id;closeDialog();location.hash='#/messages';render();toast('Message envoyé dans la démo.');}}
  if(f.id==='report-form'&&action(()=>reportPost(state,state.profile,type,id,data.reason)).ok){closeDialog();render();toast('Le profil admin a reçu votre signalement.');}
  if(f.id==='delete-form'&&action(()=>removePost(state,state.profile,type,id,!!data.series)).ok){closeDialog();render();toast('Publication retirée. Les personnes concernées ont été notifiées.');}
});
window.addEventListener('hashchange',()=>{query='';filter='Tout';closeDialog();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
window.addEventListener('storage',e=>{if(e.key===CONFIG.storageKey){state=load();closeDialog();render();toast('La démonstration a été mise à jour dans un autre onglet.');}});
persist();render();
if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>{toast('Le mode hors connexion n’a pas pu être activé. La démo reste disponible en ligne.');});});}
